import{_ as p,a0 as l,w as o,s as r,ao as h,I as t,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 下如何查看一個進程的運行時間 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下如何查看一個進程的運行時間 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下如何查看一個進程的運行時間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下如何查看一個進程的運行時間 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160801 Linux how long a process has been running","title":"在 Linux 下如何查看一個進程的運行時間","tag":"201608","desc":""},"relativePath":"201608/20160801 Linux how long a process has been running.md","filePath":"[post].md"}'),d={name:"201608/20160801 Linux how long a process has been running.md"};function g(u,s,b,k,c,f){const i=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="在-linux-下如何查看一個進程的運行時間" tabindex="-1">在 Linux 下如何查看一個進程的運行時間 <a class="header-anchor" href="#在-linux-下如何查看一個進程的運行時間" aria-label="Permalink to “在 Linux 下如何查看一個進程的運行時間”">​</a></h1><p><img src="http://s0.cyberciti.org/images/category/old/linux-logo.png" alt=""></p><blockquote><p>我是一個 Linux 系統的新手。我該如何在我的 Ubuntu 服務器上查看一個進程（或者根據進程 id 查看）已經運行了多久？</p></blockquote><p>你需要使用 ps 命令來查看關於一組正在運行的進程的信息。ps 命令提供瞭如下的兩種格式化選項。</p><ol><li>etime 顯示了自從該進程啓動以來，經歷過的時間，格式為 <code>[[DD-]hh:]mm:ss</code>。</li><li>etimes 顯示了自該進程啓動以來，經歷過的時間，以秒的形式。</li></ol><h3 id="如何查看一個進程已經運行的時間" tabindex="-1">如何查看一個進程已經運行的時間？ <a class="header-anchor" href="#如何查看一個進程已經運行的時間" aria-label="Permalink to “如何查看一個進程已經運行的時間？”">​</a></h3><p>你需要在 ps 命令之後添加 -o etimes 或者 -o etime 參數。它的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps -p {PID-HERE} -o etime</span></span>
<span class="line"><span>ps -p {PID-HERE} -o etimes</span></span></code></pre></div><h4 id="第一步-找到一個進程的-pid-openvpn-為例" tabindex="-1">第一步：找到一個進程的 PID (openvpn 為例) <a class="header-anchor" href="#第一步-找到一個進程的-pid-openvpn-為例" aria-label="Permalink to “第一步：找到一個進程的 PID (openvpn 為例)”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pidof openvpn</span></span>
<span class="line"><span>6176</span></span></code></pre></div><h4 id="第二步-openvpn-進程運行了多長時間" tabindex="-1">第二步：openvpn 進程運行了多長時間？ <a class="header-anchor" href="#第二步-openvpn-進程運行了多長時間" aria-label="Permalink to “第二步：openvpn 進程運行了多長時間？”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etime</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etimes</span></span></code></pre></div><p>隱藏輸出頭部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etime=</span></span>
<span class="line"><span>$ ps -p 6176 -o etimes=</span></span></code></pre></div><p>樣例輸出：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2016/08/How-to-check-how-long-a-process-has-been-running.jpg" alt=""></p><p>這個 6176 就是你想查看的進程的 PID。在這個例子中，我查看的是 openvpn 進程。你可以按照你的需求隨意的更換 openvpn 進程名或者是 PID。在下面的例子中，我打印了 PID、執行命令、運行時間、用户 ID、和用户組 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o pid,cmd,etime,uid,gid</span></span></code></pre></div><p>樣例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  PID CMD                             ELAPSED   UID   GID</span></span>
<span class="line"><span> 6176 /usr/sbin/openvpn --daemon        15:25 65534 65534</span></span></code></pre></div><hr>`,23)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:n(()=>[...s[0]||(s[0]=[e("http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:n(()=>[...s[2]||(s[2]=[e("VIVEK GITE",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),a(i,{href:"https://github.com/MikeCoder"},{default:n(()=>[...s[3]||(s[3]=[e("MikeCoder",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const v=p(d,[["render",g]]);export{C as __pageData,v as default};
